.menu-item {
  min-height: 48px;
  padding: 0 18px;
}

.menu-rail-nav {
  gap: 0;
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.menu-group {
  display: grid;
  align-content: start;
}

.menu-group-center {
  align-self: center;
}

.menu-group-bottom {
  align-self: end;
}

.menu-separator {
  height: 1px;
  margin: var(--space-1) var(--space-3);
  background: var(--line);
  opacity: .7;
}

.menu-rail.collapsed {
  width: 56px;
}

@media (max-width: 1100px) {
  .menu-rail.collapsed,
  .menu-rail.expanded {
    width: 100%;
  }

  .menu-rail-nav {
    grid-template-rows: none;
  }

  .menu-group {
    display: contents;
  }

  .menu-separator {
    grid-column: 1 / -1;
  }
}

.menu-item:hover,
.menu-item.active {
  border-color: transparent;
}

.menu-item.active {
  box-shadow: inset 4px 0 0 var(--accent);
}

.menu-item-copy small {
  font-size: var(--font-size-xs);
}

.app-context-bar {
  min-width: 0;
  min-height: var(--context-bar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 var(--space-3);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.app-context-identity,
.app-context-status {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.app-context-icon {
  flex: 0 0 auto;
  color: var(--muted);
}

.app-context-identity strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  letter-spacing: -.01em;
  white-space: nowrap;
}

.app-context-identity span {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-badge,
.context-live-toggle,
.context-theme-toggle,
.context-language-select {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.status-badge {
  padding: 0 7px;
}

.status-badge-success {
  border-color: color-mix(in srgb, var(--success) 42%, var(--line));
  background: var(--success-soft);
  color: var(--success);
}

.status-badge-warning {
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
  background: var(--warning-soft);
  color: var(--warning);
}

.status-badge-accent {
  border-color: var(--accent-border);
  background: var(--accent-soft);
  color: var(--accent);
}

.context-live-toggle,
.context-theme-toggle {
  cursor: pointer;
  padding: 0 8px;
}

.context-live-toggle > span {
  width: 6px;
  height: 6px;
  margin-right: 5px;
  border-radius: 50%;
  background: currentColor;
}

.context-live-toggle.is-success {
  border-color: color-mix(in srgb, var(--success) 42%, var(--line));
  background: var(--success-soft);
  color: var(--success);
}

.context-live-toggle.is-warning {
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
  background: var(--warning-soft);
  color: var(--warning);
}

.context-language-select {
  max-width: 108px;
  cursor: pointer;
  padding: 0 22px 0 7px;
}

.context-live-toggle:hover,
.context-theme-toggle:hover {
  border-color: var(--accent-border);
  color: var(--accent);
}

.main-tab-view,
.dashboard-view {
  padding: var(--space-3);
}

.main-tab-view {
  padding-top: var(--space-3);
}

.app-context-bar-compact {
  margin-bottom: var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
}

@media (max-width: 720px) {
  .app-context-identity span,
  .app-context-status .status-badge {
    display: none;
  }

  .app-context-bar {
    padding: 0 var(--space-2);
  }
}

.context-theme-toggle.icon-only {
  width: 28px;
  min-width: 28px;
  padding: 0;
}
