export function AlertsPane({ onSaved, onOpenMonitoringTargets }: AlertsPaneProps) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [profiles, setProfiles] = useState<AlertProfile[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileFormat, setProfileFormat] = useState(false);
  const [policyTab, setPolicyTab] = useState<PolicyTab>("rules");
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => (tab === "all" || ruleTab(row) === tab) && matchesRuleMetric(row, settings?.metrics ?? [], metricQuery)), [rows, settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };
  const startProfiles = () => { setProfileFormat(true); setProfiles([{ id: "default", title: "Default", rule_ids: [] }]); setAssignments([]); setPolicyTab("profiles"); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = profileFormat ? { ...(settings.document._note ? { _note: settings.document._note } : {}), rules: rows, profiles, assignments } : { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      onSaved(next.document.alerts ?? next.document.rules ?? []);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame" header={<PaneHeader title="Alert policies" icon="alertRules" meta="Rules, profiles, and monitoring target assignments" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Rules define alert conditions, profiles combine rules, and assignments apply profiles to protocol defaults or Monitoring targets. Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-policy-navigation">
        <div className="alerts-tabs" role="tablist" aria-label="Alert policy section">
          {([ ["rules", "Rules", rows.length], ["profiles", "Profiles", profiles.length], ["assignments", "Assignments", assignments.length] ] as const).map(([key, label, count]) => <button key={key} type="button" role="tab" aria-selected={policyTab === key} className={"alerts-tab" + (policyTab === key ? " is-active" : "")} onClick={() => setPolicyTab(key)}>{label}<span>{count}</span></button>)}
        </div>
        <div className="alerts-policy-flow" aria-label="Alert policy relationship"><span>Rules</span><b>→</b><span>Profiles</span><b>→</b><span>Assignments</span><b>→</b><button type="button" onClick={onOpenMonitoringTargets}>Monitoring targets</button></div>
      </section>
      {policyTab === "rules" && <>
      <section className="maintenance-section alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <label className="alerts-metric-search">Find metrics<input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="bitrate, rtt, packet…" /></label>
      </section>
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><colgroup><col className="alerts-col-index" /><col className="alerts-col-enabled" /><col className="alerts-col-id" /><col className="alerts-col-target" /><col className="alerts-col-metric" /><col className="alerts-col-rule" /><col className="alerts-col-trigger" /><col className="alerts-col-recovery" /><col className="alerts-col-severity" /><col className="alerts-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Rule ID</th><th>Target</th><th>Metric</th><th>Rule</th><th>Trigger</th><th>Recovery</th><th>Severity</th><th /></tr></thead><tbody>
        {visibleRows.map(({ row, index }) => <AlertRow key={index} index={index} row={row} metrics={settings?.metrics ?? []} busy={state === "saving"} onUpdate={updateRow} onRemove={removeRow} />)}
        {visibleRows.length === 0 && <tr><td colSpan={10} className="alerts-empty">{metricQuery.trim() ? "No matching alert rules in this tab." : <>No {tab === "all" ? "alert" : tab} rules.{tab === "all" ? " Choose a protocol tab to add one." : " Add a rule to begin."}</>}</td></tr>}
      </tbody></table></div><div className="protocol-map-row-actions">{tab !== "all" && <button type="button" className="maintenance-secondary-button button-with-icon" disabled={!settings || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add {tab === "general" ? "general" : tab} rule</button>}</div>
      </section>
      </>}
      {policyTab !== "rules" && !profileFormat && <section className="maintenance-section alerts-profile-migration"><div><h2>Use profiles and assignments</h2><p>Convert this alert policy to the profile format before assigning rules to Monitoring targets.</p></div><button type="button" className="maintenance-secondary-button" disabled={state === "saving"} onClick={startProfiles}>Enable profiles</button></section>}
      {policyTab === "profiles" && profileFormat && <ProfilesPane profiles={profiles} assignments={assignments} rules={rows} metrics={settings?.metrics ?? []} busy={state === "saving"} onProfiles={setProfiles} onAssignments={setAssignments} />}
      {policyTab === "assignments" && profileFormat && <AssignmentsPane assignments={assignments} targets={settings?.monitoringTargets ?? []} profiles={profiles} busy={state === "saving"} onAssignments={setAssignments} />}
      <footer className="maintenance-actions"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading alert rules…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function copyProfile(profile: AlertProfile): AlertProfile { return { ...profile, rule_ids: [...profile.rule_ids] }; }
function profileIsEqual(left: AlertProfile, right: AlertProfile) { return left.id === right.id && left.title === right.title && left.rule_ids.length === right.rule_ids.length && left.rule_ids.every((id, index) => id === right.rule_ids[index]); }
function ruleCondition(rule: AlertRule) { if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + String(rule.delta_threshold ?? "—") + " / " + String(rule.recover_after_sec ?? 3) + "s"; return rule.metric + " " + (rule.operator ?? ">") + " " + String(rule.error_threshold ?? "—") + " (recover " + String(rule.recover_threshold ?? "—") + ")"; }

type TargetPickerProps = { value: string; targetType: "single" | "group"; targets: MonitoringTargetDefinition[]; busy: boolean; onChange: (id: string, targetType: "single" | "group") => void };
