  const selected = targets.find((target) => target.id === value);
  const label = (target: MonitoringTargetDefinition) => target.id + " · " + target.target_type + " · " + target.proto + (target.title ? " · " + target.title : "");
  return <><div className="alerts-target-picker"><select value={selected?.id ?? ""} disabled={busy} aria-label="Select Monitoring Target" onChange={(event) => { const target = targets.find((item) => item.id === event.target.value); if (target) onChange(target.id, target.target_type); }}><option value="">Select target</option>{targets.map((target) => <option key={target.id} value={target.id}>{label(target)}</option>)}</select><input list="monitoring-target-ids" value={value} disabled={busy} onChange={(event) => { const target = targets.find((item) => item.id === event.target.value); onChange(event.target.value, target?.target_type ?? targetType); }} placeholder="Or enter orphan ID" aria-label="Monitoring Target ID" /></div><datalist id="monitoring-target-ids">{targets.map((target) => <option key={target.id} value={target.id}>{label(target)}</option>)}</datalist></>;
}

type ProfilesPaneProps = { profiles: AlertProfile[]; assignments: AlertAssignment[]; rules: AlertRule[]; metrics: AlertMetricDefinition[]; busy: boolean; onProfiles: (profiles: AlertProfile[]) => void; onAssignments: (assignments: AlertAssignment[]) => void };
function ProfilesPane({ profiles, assignments, rules, metrics, busy, onProfiles, onAssignments }: ProfilesPaneProps) {
  const [selectedId, setSelectedId] = useState<string | null>(profiles[0]?.id ?? null);
