  const selectProfile = (profile: AlertProfile) => { if (editing && draft && selected && !profileIsEqual(draft, selected) && !window.confirm("Discard unsaved profile changes and switch profiles?")) return; setSelectedId(profile.id); setDraft(copyProfile(profile)); setEditing(false); };
  const newProfile = () => { const profile = { id: nextProfileId(profiles), title: "", rule_ids: [] }; onProfiles([...profiles, profile]); setSelectedId(profile.id); setDraft(copyProfile(profile)); setEditing(true); };
