type ProfileDetailProps = { profile: AlertProfile | null; draft: AlertProfile | null; editing: boolean; rules: AlertRule[]; metrics: AlertMetricDefinition[]; assignments: AlertAssignment[]; busy: boolean; onEdit: () => void; onCancel: () => void; onSave: () => void; onDraft: (profile: AlertProfile) => void; onToggleRule: (id: string) => void; onDelete: () => void };
