ic) => metric.key === rule.metric)} /></td><td>{rule.severity ?? "warning"}</td><td>{rule.enabled === false ? "Off" : "On"}</td></tr>)}{shownRules.length === 0 && <tr><td colSpan={editing ? 5 : 4} className="alerts-empty">No rules selected.</td></tr>}</tbody></table></div>{!editing && <><h4>Applied assignments</h4><ul className="alerts-assignment-summary">{assignments.map((assignment, index) => <li key={index}>{assignmentSummary(assignment)}</li>)}{assignments.length === 0 && <li>No assignments.</li>}</ul></>}</aside>;
