import type { CSSProperties } from "react";
import type { AlertRule, InterfaceListItem, InterfaceMetricsResponse } from "../types/api";
import { MetricChart, type ChartAlertContext } from "./MetricChart";
import { Icon } from "./ui/Icon";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { useI18n } from "../i18n";
import type { ResourceLoadState } from "../hooks/useResourceLoadState";
import { PaneLoadingOverlay } from "./ui/PaneLoadingOverlay";

type InterfaceDetailPaneProps = {
  item: InterfaceListItem | null;
  metrics: InterfaceMetricsResponse | null;
  alertRules: AlertRule[];
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
  embedded?: boolean;
  onOpenTargetPicker?: () => void;
  loadState?: ResourceLoadState;
};

export function InterfaceDetailPane({
  item,
  metrics,
  alertRules,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls,
  embedded = false,
  onOpenTargetPicker,
  loadState
}: InterfaceDetailPaneProps) {
  const { t } = useI18n();
  const alertContext = { rules: alertRules, target: "interface" as const };
  if (!item) {
    return <aside className="detail-pane empty-state">
      <div>
        <p>Select an interface or stream.</p>
        {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
      </div>
    </aside>;
  }

  return (
    <aside className={["detail-pane", "pane-loading-host", "interface-detail-pane", mode === "overview" ? "graph-mode" : "", embedded ? "detail-pane-embedded" : ""].filter(Boolean).join(" ")}>
      {!embedded && <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <Icon className="pane-header-icon" name="detail" size={14} /><span className="kind-pill">NIC</span>
          <h2>{item.name}</h2>
          <p>{item.available ? "Available" : "Unavailable"} / {item.streamCount} stream{item.streamCount === 1 ? "" : "s"} / last seen {item.lastSeen ? formatRelativeTime(item.lastSeen) : "waiting"}</p>
        </div>
        <div className="detail-header-actions">
          {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Inspector width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize Inspector pane"><Icon name="widthMaximize" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore Inspector pane width"><Icon name="widthRestore" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink Inspector pane"><Icon name="widthMinimize" size={16} /></button>
            </div>
          )}
          <div className="detail-mode-tabs" role="tablist" aria-label="NIC Inspector mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Metrics</button>
          </div>
        </div>
      </header>}

      <div className="detail-body">
        {mode === "overview" ? (
          <InterfaceOverview item={item} metrics={metrics} alertContext={alertContext} />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="RX Bitrate" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
              <Stat label="TX Bitrate" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
              <Stat label="Link" value={formatLinkSummary(item)} />
              <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
              <Stat label="Streams" value={String(item.streamCount)} />
            </div>

            <BandwidthUsagePanel item={item} />

            <section className="stats-section">
              <h3>NIC Stats</h3>
              <div className="stats-grid">
                <Stat label="RX Packets" value={formatNumber(item.rx.packets.value ?? 0)} />
                <Stat label="TX Packets" value={formatNumber(item.tx.packets.value ?? 0)} />
                <Stat label="RX Drops" value={formatNumber(item.rx.dropped.value ?? 0)} />
                <Stat label="TX Drops" value={formatNumber(item.tx.dropped.value ?? 0)} />
                <Stat label="RX Errors" value={formatNumber(item.rx.errors.value ?? 0)} />
                <Stat label="TX Errors" value={formatNumber(item.tx.errors.value ?? 0)} />
              </div>
            </section>

            <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} color="var(--chart-rx)" alertContext={alertContext} />
            <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} color="var(--chart-tx)" alertContext={alertContext} />

            <section className="metric-group">
              <h3>Packets / Drops / Errors</h3>
              <div className="chart-stack">
                <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={150} color="var(--chart-rx-packets)" alertContext={alertContext} />
                <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={150} color="var(--chart-tx-packets)" alertContext={alertContext} />
                <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={130} color="var(--chart-rx-dropped)" alertContext={alertContext} />
                <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={130} color="var(--chart-tx-dropped)" alertContext={alertContext} />
                <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={130} color="var(--chart-rx-errors)" alertContext={alertContext} />
                <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={130} color="var(--chart-tx-errors)" alertContext={alertContext} />
